29	func (d *DB) DeleteUser(ctx context.Context, delete *store.DeleteUser) (*store.DeleteUserResult, error) {
30		tx, err := d.db.BeginTx(ctx, nil)
31		if err != nil {
32			return nil, errors.Wrap(err, "failed to begin delete user transaction")
33		}
34		defer func() {
35			_ = tx.Rollback()
36		}()
37	
38		targets, err := collectDeleteUserTargets(ctx, tx, delete.ID)
39		if err != nil {
40			return nil, errors.Wrap(err, "failed to collect delete user targets")
41		}
42	
43		if err := deleteUserTargetsTx(ctx, tx, delete.ID, targets); err != nil {
44			return nil, errors.Wrap(err, "failed to delete user targets")
45		}
46	
47		if store.GetDeleteUserFailpoint(ctx) == store.DeleteUserFailpointBeforeCommit {
48			return nil, errors.New("delete user failpoint before commit")
49		}
50	
51		if err := tx.Commit(); err != nil {
52			return nil, errors.Wrap(err, "failed to commit delete user transaction")
53		}
54	
55		return &store.DeleteUserResult{
56			Attachments:     targets.attachments,
57			UserSettingKeys: targets.userSettingKeys,
58		}, nil
59	}
60	
61	func collectDeleteUserTargets(ctx context.Context, tx *sql.Tx, userID int32) (*deleteUserTargetSet, error) {
62		targets := &deleteUserTargetSet{}
63	
64		memos, err := listDeleteUserMemoTree(ctx, tx, userID)
65		if err != nil {
66			return nil, err
67		}
68		targets.memos = memos
69	
70		attachments, err := listDeleteUserAttachments(ctx, tx, userID, memoIDsFromRefs(memos))
71		if err != nil {
72			return nil, err
73		}
74		targets.attachments = attachments
75		targets.attachmentIDs = attachmentIDsFromList(attachments)
76	
77		userSettingKeys, err := listDeleteUserSettingKeys(ctx, tx, userID)
78		if err != nil {
79			return nil, err
80		}
81		targets.userSettingKeys = userSettingKeys
82	
83		inboxIDs, err := listDeleteUserInboxIDs(ctx, tx, userID, memoIDSetFromRefs(memos))
84		if err != nil {
85			return nil, err
86		}
87		targets.inboxIDs = inboxIDs
88	
89		return targets, nil
90	}
