284	func listDeleteUserDirectInboxIDs(ctx context.Context, tx *sql.Tx, userID int32) ([]int32, error) {
285		rows, err := tx.QueryContext(ctx, `
286			SELECT id
287			FROM inbox
288			WHERE sender_id = `+deleteUserPlaceholder(1)+`
289				OR receiver_id = `+deleteUserPlaceholder(2), userID, userID)
290		if err != nil {
291			return nil, err
292		}
293		defer rows.Close()
294	
295		inboxIDs := make([]int32, 0)
296		for rows.Next() {
297			var inboxID int32
298			if err := rows.Scan(&inboxID); err != nil {
299				return nil, err
300			}
301			inboxIDs = append(inboxIDs, inboxID)
302		}
303		if err := rows.Err(); err != nil {
304			return nil, err
305		}
306	
